import sqlite3
con = sqlite3.connect('/root/data/eventlogs.db')
cur = con.cursor()
with open('/tmp/malicious_list.txt') as f:
    mal_ids = {line.split(' | ')[0] for line in f if line.strip()}
cur.execute('SELECT event_id, event_code, host, user, image FROM events')
non_mal = [r for r in cur.fetchall() if r[0] not in mal_ids]
py_counts = {}
for r in non_mal:
    key = (r[2], r[1], r[4] or '')
    py_counts[key] = py_counts.get(key, 0) + 1
for k, v in sorted(py_counts.items(), key=lambda x: x[1], reverse=True):
    if v > 10:
        print(f'{k[0]} | Code {k[1]} | Image: {k[2]} | Count: {v}')
